<?php $title='Sonderberichtsuche'; ?>
<div class="page-header"><div><p class="eyebrow">Sonderberichte</p><h1>Suche & Archiv</h1><p>Berichte nach Zeitraum, Einsatzart, Status, Personen, Beteiligten und Volltext filtern.</p></div></div><div class="panel"><form method="get" action="<?= e(url('special-reports/search')) ?>" class="form-grid"><label>Von<input type="date" name="from" value="<?= e($filters['from']) ?>"></label><label>Bis<input type="date" name="to" value="<?= e($filters['to']) ?>"></label><label>Einsatzart<select name="type_id"><option value="">Alle</option><?php foreach($types as $t):?><option value="<?= (int)$t['id'] ?>" <?= (int)$filters['type_id']===(int)$t['id']?'selected':'' ?>><?= e($t['name']) ?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">Alle</option><?php foreach(['draft'=>'Entwurf','in_progress'=>'In Bearbeitung','revision_required'=>'Nachbearbeitung','completed'=>'Ungeprüft','reviewed'=>'Geprüft'] as $v=>$l):?><option value="<?= e($v) ?>" <?= $filters['status']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach;?></select></label><label>Ersteller<select name="creator_id"><option value="">Alle</option><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>" <?= (int)$filters['creator_id']===(int)$u['id']?'selected':'' ?>><?= e($u['last_name'].', '.$u['first_name']) ?></option><?php endforeach;?></select></label><label>Beteiligter Mitarbeiter<select name="staff_id"><option value="">Alle</option><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>" <?= (int)$filters['staff_id']===(int)$u['id']?'selected':'' ?>><?= e($u['last_name'].', '.$u['first_name']) ?></option><?php endforeach;?></select></label><label>Betroffene Person<input name="person" value="<?= e($filters['person']) ?>"></label><label>Volltext<input name="q" value="<?= e($filters['q']) ?>"></label><label class="check-row"><input type="checkbox" name="attachments" value="1" <?= $filters['attachments']?'checked':'' ?>><span>Nur mit Anlagen</span></label><div class="form-actions"><button class="button primary" type="submit">Suchen</button></div></form></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Nummer</th><th>Datum</th><th>Einsatzart</th><th>Status</th><th>Ersteller</th><th></th></tr></thead><tbody><?php foreach($result['items'] as $r):?><tr><td><?= e(str_pad((string)$r['report_number'],4,'0',STR_PAD_LEFT).'/'.$r['report_year']) ?></td><td><?= e((new DateTimeImmutable($r['incident_date']))->format('d.m.Y')) ?></td><td><?= e($r['report_type_name']) ?></td><td><span class="badge status-<?= e($r['status']) ?>"><?= e($r['status']) ?></span></td><td><?= e($r['creator_name']??'–') ?></td><td><a class="button ghost compact" href="<?= e(url('special-reports/'.$r['id'])) ?>">Öffnen</a></td></tr><?php endforeach;?><?php if($result['items']===[]):?><tr><td colspan="6" class="empty">Keine Treffer.</td></tr><?php endif;?></tbody></table></div><div class="pagination"><span><?= (int)$result['total'] ?> Treffer</span><span>Seite <?= (int)$result['page'] ?> / <?= (int)$result['pages'] ?></span></div></div>
